  LiveBlocks.insert(L->getHeader());

  auto MarkLiveEdge = [&](BasicBlock *From, BasicBlock *To) {
    assert(LiveBlocks.count(From) && "Must be live!");
    LiveBlocks.insert(To);
    LiveEdges.insert({ From, To });
